<?php require_once "config/database.php";require_once "includes/functions.php";start_session();$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$st=$pdo->prepare("SELECT * FROM users WHERE email=? AND status='active'");$st->execute([trim($_POST["email"]??"")]);$u=$st->fetch();if($u&&password_verify($_POST["password"]??"",$u["password_hash"])){$_SESSION["user"]= ["id"=>$u["id"],"name"=>$u["name"],"email"=>$u["email"],"role"=>$u["role"]];header("Location: index.php");exit;} $error="Invalid email or password.";}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | JKtech.lk</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/navbar.php";?><main class="auth-wrap"><form class="auth-card" method="post"><span class="eyebrow">ACCOUNT</span><h1>Welcome back.</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn primary">Login</button><p>New customer? <a href="register.php">Create an account</a></p></form></main></body></html>